    /** A message kind's glyph (inbox preview, reply quote). */
    fun of(glyph: Glyph): ImageVector = when (glyph) {
        Glyph.PHOTO -> photo
        Glyph.VIDEO -> video
        Glyph.WAVEFORM -> voice
        Glyph.DOC -> doc
        Glyph.STICKER -> sticker
        Glyph.REEL -> reel
        Glyph.POST -> photo
        Glyph.STORY -> story
        Glyph.LINK -> link
        Glyph.VIEW_ONCE -> viewOnce
        Glyph.UNSENT -> unsend
        Glyph.UNSUPPORTED -> unsupported
    }
}
